dom.bannerCss:
.lx-hero{position:relative;overflow:hidden;isolation:isolate;background:#2c2118;color:#fff;min-height:230px;display:flex;align-items:center}
.lx-hero__bilder{position:absolute;inset:0;display:grid;grid-template-columns:repeat(4,1fr);z-index:-2}
.lx-hero__bilder img{width:100%;height:100%;object-fit:cover;display:block}
.lx-hero__bilder img.lx-hero__eins{grid-column:1/-1}
.lx-hero::before{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(90deg,rgba(24,17,10,.88) 0%,rgba(24,17,10,.66) 50%,rgba(24,17,10,.34) 100%)}
.lx-hero__text{width:100%;max-width:var(--page-width,1200px);margin:0 auto;padding:2.4rem 1.5rem 2.2rem;box-sizing:border-box}
.lx-hero h1{margin:0 0 .6rem;color:#fff!important;font-size:clamp(2.2rem,5.5vw,3.5rem);line-height:1.08;font-weight:700;letter-spacing:-.01em;text-shadow:0 2px 14px rgba(0,0,0,.45)}
.lx-hero__beschr,.lx-hero__beschr p{color:#f4ede0!important;margin:.4rem 0 0;max-width:62rem;text-shadow:0 1px 8px rgba(0,0,0,.5)}
.lx-hero__beschr a{color:#fff!important;text-decoration:underline}
@media(max-width:749px){.lx-hero__bilder{grid-template-columns:repeat(2,1fr)}.lx-hero__bilder img:nth-child(n+3):not(.lx-hero__eins){display:none}.lx-hero__text{padding:1.8rem 1rem 1.6rem}}

